const removeSubstitution = `-- name: RemoveSubstitution :execrows
UPDATE dish_substitutions SET removed_at = now() WHERE id = $1 AND dish_version_id = $2 AND removed_at IS NULL
`

type RemoveSubstitutionParams struct {
	ID            uuid.UUID `json:"id"`
	DishVersionID uuid.UUID `json:"dish_version_id"`
}

func (q *Queries) RemoveSubstitution(ctx context.Context, arg RemoveSubstitutionParams) (int64, error) {
	result, err := q.db.Exec(ctx, removeSubstitution, arg.ID, arg.DishVersionID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

